Author: Daniel Stenberg <daniel@haxx.se>
Date:   Mon Oct 6 10:20:45 2025 +0200

    ftp: improve fragile check for first digit > 3

    In a case where rubbish would be sent in the line something that isn't a
    digit could be first in line and treated as less than '3'. Prevent this
    risk by first doing a check that the byte is a digit.

    Reported-by: Joshua Rogers
    Closes #18870

diff --git a/lib/ftp.c b/lib/ftp.c
index 77db98c00..402c13a07 100644
--- a/lib/ftp.c
+++ b/lib/ftp.c
@@ -352,205 +352,208 @@ struct ftp_cw_lc_ctx {
 static CURLcode ftp_cw_lc_write(struct Curl_easy *data,
                                 struct Curl_cwriter *writer, int type,
                                 const char *buf, size_t blen)
 {
   static const char nl = '\n';
   struct ftp_cw_lc_ctx *ctx = writer->ctx;
   struct ftp_conn *ftpc = Curl_conn_meta_get(data->conn, CURL_META_FTP_CONN);

   if(!ftpc)
     return CURLE_FAILED_INIT;

   if(!(type & CLIENTWRITE_BODY) || ftpc->transfertype != 'A')
     return Curl_cwriter_write(data, writer->next, type, buf, blen);

   /* ASCII mode BODY data, convert lineends */
   while(blen) {
     /* do not pass EOS when writing parts */
     int chunk_type = (type & ~CLIENTWRITE_EOS);
     const char *cp;
     size_t chunk_len;
     CURLcode result;

     if(ctx->newline_pending) {
       if(buf[0] != '\n') {
         /* previous chunk ended in '\r' and we do not see a '\n' in this one,
          * need to write a newline. */
         result = Curl_cwriter_write(data, writer->next, chunk_type, &nl, 1);
         if(result)
           return result;
       }
       /* either we just wrote the newline or it is part of the next
        * chunk of bytes we write. */
       ctx->newline_pending = FALSE;
     }

     cp = memchr(buf, '\r', blen);
     if(!cp)
       break;

     /* write the bytes before the '\r', excluding the '\r' */
     chunk_len = cp - buf;
     if(chunk_len) {
       result = Curl_cwriter_write(data, writer->next, chunk_type,
                                   buf, chunk_len);
       if(result)
         return result;
     }
     /* skip the '\r', we now have a newline pending */
     buf = cp + 1;
     blen = blen - chunk_len - 1;
     ctx->newline_pending = TRUE;
   }

   /* Any remaining data does not contain a '\r' */
   if(blen) {
     DEBUGASSERT(!ctx->newline_pending);
     return Curl_cwriter_write(data, writer->next, type, buf, blen);
   }
   else if(type & CLIENTWRITE_EOS) {
     /* EndOfStream, if we have a trailing cr, now is the time to write it */
     if(ctx->newline_pending) {
       ctx->newline_pending = FALSE;
       return Curl_cwriter_write(data, writer->next, type, &nl, 1);
     }
     /* Always pass on the EOS type indicator */
     return Curl_cwriter_write(data, writer->next, type, buf, 0);
   }
   return CURLE_OK;
 }

